UPDATE UZM0SH
   SET misu_ija = #{misuIja}
     , ija_tax  = #{ijaTax}
     , sury_aek = #{suryAek}
     , mod_user = #{modUser}
     , mod_dt   = SYSDATE
 WHERE corp_gr    = #{corpGr}
   AND sanghw_ymd = TO_DATE(REPLACE(#{sanghwYmd}, '-', ''), 'YYYYMMDD')
   AND fund_cd    = #{fundCd}
   AND jm_gr      = #{jmGr}
   AND jm_cd      = #{jmCd}
   AND buy_date   = #{buyDate}
